// rc_enemy.c - generated by split_c.py from RayCaster.c
#include "rc_priv.h"



static void BuildFlow(void)
{
    uint16_t i, head = 0, tail = 0, cell, nb;
    int16_t tx = (int16_t)(rc_px >> 10);
    int16_t ty = (int16_t)(rc_py >> 10);
    int16_t x, y, nx, ny;

    for(i = 0; i < RC_MAP_CELLS; i++) rc_flow[i] = 0xFFFFu;
    rc_flowTx = tx;
    rc_flowTy = ty;
    if((uint16_t)tx >= RC_MAP_W || (uint16_t)ty >= RC_MAP_H) return;

    cell = (uint16_t)(((uint16_t)ty << RC_MAP_SHIFT) + (uint16_t)tx);
    rc_flow[cell] = 0;
    rc_flowQ[tail++] = cell;

    /* Queue BFS avoids the old repeated full-map scans; important on 32x32. */
    while(head < tail)
    {
        cell = rc_flowQ[head++];
        x = (int16_t)(cell & (RC_MAP_W - 1u));
        y = (int16_t)(cell >> RC_MAP_SHIFT);
        for(i = 0; i < 4; i++)
        {
            nx = (int16_t)(x + rc_kNbDx[i]);
            ny = (int16_t)(y + rc_kNbDy[i]);
            if((uint16_t)nx >= RC_MAP_W || (uint16_t)ny >= RC_MAP_H) continue;
            if(Solid(nx, ny)) continue;
            nb = (uint16_t)(((uint16_t)ny << RC_MAP_SHIFT) + (uint16_t)nx);
            if(rc_flow[nb] != 0xFFFFu) continue;
            rc_flow[nb] = (uint16_t)(rc_flow[cell] + 1u);
            if(tail < RC_MAP_CELLS) rc_flowQ[tail++] = nb;
        }
    }
}


void rc_EnsureFlow(void)
{
    if((int16_t)(rc_px >> 10) != rc_flowTx || (int16_t)(rc_py >> 10) != rc_flowTy)
        BuildFlow();
}


// Is the straight line between two points free of walls?
static bool LineClear(int16_t x0, int16_t y0, int16_t x1, int16_t y1)
{
    int16_t dx = (int16_t)(x1 - x0);
    int16_t dy = (int16_t)(y1 - y0);
    int16_t n  = (int16_t)(Dist10(dx, dy) / 320);
    int16_t i;

    for(i = 1; i < n; i++)
        if(Blocked((int16_t)(x0 + (int16_t)(((int32_t)dx * i) / n)),
                   (int16_t)(y0 + (int16_t)(((int32_t)dy * i) / n)), 220))
            return false;
    return true;
}


// Where an enemy at (ex, ey) should head, as a vector (dx, dy).
static void SteerTarget(int16_t ex, int16_t ey, int16_t *tdx, int16_t *tdy)
{
    int16_t  etx = (int16_t)(ex >> 10);
    int16_t  ety = (int16_t)(ey >> 10);
    int16_t  nx, ny;
    uint16_t d, i;

    *tdx = (int16_t)(rc_px - ex);                        // default: straight at the player
    *tdy = (int16_t)(rc_py - ey);

    if((uint16_t)etx >= RC_MAP_W || (uint16_t)ety >= RC_MAP_H) return;
    d = rc_flow[((uint16_t)ety << RC_MAP_SHIFT) + (uint16_t)etx];
    if(d <= 1u || d == 0xFFFFu) return;                 // next to the player / no route
    if(LineClear(ex, ey, rc_px, rc_py)) return;           // can see the player

    for(i = 0; i < 4; i++)                              // step to the tile that is closer
    {
        nx = (int16_t)(etx + rc_kNbDx[i]);
        ny = (int16_t)(ety + rc_kNbDy[i]);
        if((uint16_t)nx >= RC_MAP_W || (uint16_t)ny >= RC_MAP_H) continue;
        if(rc_flow[((uint16_t)ny << RC_MAP_SHIFT) + (uint16_t)nx] == (uint16_t)(d - 1u))
        {
            *tdx = (int16_t)((nx << 10) + 512 - ex);
            *tdy = (int16_t)((ny << 10) + 512 - ey);
            return;
        }
    }
}


void rc_UpdateEnemies(void)
{
    uint16_t i, j;
    int16_t  dx, dy, dist, sp, mx, my, nx, ny;

    for(i = 0; i < RC_MAX_ENEMIES; i++)
    {
        Enemy          *e = &rc_en[i];
        const EnemyDef *d;

        if(!e->alive) continue;
        d = &rc_kEnemy[e->type];

        if(e->flash) e->flash--;

        if(e->burn)                                     // burning: 1 damage every 16 frames
        {
            e->burn--;
            if((e->burn & 15u) == 0)
            {
                rc_DamageEnemyEx(e, 1, 0, 0, true);
                if(!e->alive) continue;
            }
        }

        if(e->freeze) { e->freeze--; continue; }        // frozen solid: no move, no attack

        sp = d->speed;
        if(e->slow) { e->slow--; sp >>= 1; }

        if(e->type == ET_LICH)
        {
            bool angry = (e->hp < RC_BOSS_HP / 2);

            e->aux++;
            if(angry) sp += (sp >> 2);
            if(e->aux >= 220)                           // charge!
            {
                sp *= 3;
                if(e->aux >= 265) e->aux = 0;
            }

            e->aux2++;
            if(e->aux2 >= (angry ? 110u : 170u))        // summon skeletons
            {
                e->aux2 = 0;
                rc_LichSummon(e, angry ? 3u : 2u);
            }
        }
        else if(e->type == ET_BEHOLDER)
        {
            e->aux++;
            if(e->aux >= rc_BeholderCadence())
            {
                e->aux = 0;
                rc_BeholderShoot(e);
            }
        }
        else if(e->type == ET_DRAGON)
        {
            e->aux++;
            if(e->aux >= 180u) e->aux = 0;
            /* Two short breath volleys, then a telegraphed tail sweep. */
            if(e->aux == 58u || e->aux == 72u) rc_DragonBreath(e);
        }

        dx   = rc_px - e->x;
        dy   = rc_py - e->y;
        dist = Dist10(dx, dy);

        if(e->type == ET_BEHOLDER)
        {
            // Keeps 2.6 - 3.8 tiles away: closes in, backs off, or drifts sideways.
            if(dist > 0)
            {
                if(dist > 3800)
                {
                    int16_t sdx, sdy, sd;

                    SteerTarget(e->x, e->y, &sdx, &sdy);
                    sd = Dist10(sdx, sdy);
                    if(sd < 1) sd = 1;
                    mx = (int16_t)(((int32_t)sdx * sp) / sd);
                    my = (int16_t)(((int32_t)sdy * sp) / sd);
                }
                else if(dist < 2600)
                {
                    mx = (int16_t)(-(((int32_t)dx * (sp + (sp >> 1))) / dist));
                    my = (int16_t)(-(((int32_t)dy * (sp + (sp >> 1))) / dist));
                }
                else
                {
                    int16_t sgn = (i & 1u) ? 1 : -1;

                    mx = (int16_t)(sgn * (((int32_t)-dy * (sp >> 1)) / dist));
                    my = (int16_t)(sgn * (((int32_t) dx * (sp >> 1)) / dist));
                }

                nx = e->x + mx;
                if(!Blocked(nx, e->y, 230)) e->x = nx;
                ny = e->y + my;
                if(!Blocked(e->x, ny, 230)) e->y = ny;
            }
        }
        else if(dist > 200)
        {
            int16_t sdx, sdy, sd;

            SteerTarget(e->x, e->y, &sdx, &sdy);
            sd = Dist10(sdx, sdy);
            if(sd < 1) sd = 1;
            mx = (int16_t)(((int32_t)sdx * sp) / sd);
            my = (int16_t)(((int32_t)sdy * sp) / sd);

            nx = e->x + mx;
            if(!Blocked(nx, e->y, 230)) e->x = nx;
            ny = e->y + my;
            if(!Blocked(e->x, ny, 230)) e->y = ny;
        }

        if(e->type == ET_DRAGON)
        {
            if(e->aux == 132u && dist < 2050) rc_HurtPlayer();   // tail-whip impact frame
        }
        else if(dist < d->reach) rc_HurtPlayer();
    }

    // Keep them from stacking into one blob.
    for(i = 0; i + 1 < RC_MAX_ENEMIES; i++)
    {
        if(!rc_en[i].alive) continue;
        for(j = i + 1; j < RC_MAX_ENEMIES; j++)
        {
            if(!rc_en[j].alive) continue;
            dx = rc_en[i].x - rc_en[j].x;
            dy = rc_en[i].y - rc_en[j].y;
            if(Abs16(dx) < 300 && Abs16(dy) < 300)
            {
                int16_t px = (dx >= 0) ? 5 : -5;
                int16_t py = (dy >= 0) ? 5 : -5;

                if(!Blocked(rc_en[i].x + px, rc_en[i].y, 230)) rc_en[i].x += px;
                if(!Blocked(rc_en[i].x, rc_en[i].y + py, 230)) rc_en[i].y += py;
                if(!Blocked(rc_en[j].x - px, rc_en[j].y, 230)) rc_en[j].x -= px;
                if(!Blocked(rc_en[j].x, rc_en[j].y - py, 230)) rc_en[j].y -= py;
            }
        }
    }
}
